public:
    int minimumXORSum(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        int totalStates = 1 << n;
        vector<int> dp(totalStates, 1e9);
        dp[0] = 0;

        for (int mask = 0; mask < totalStates; ++mask) {
            int i = __builtin_popcount(mask);
            if (i >= n) continue;
            for (int j = 0; j < n; ++j) {
