import java.util.*;

class Solution {
    public int minimumXORSum(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int totalStates = 1 << n;
        int[] dp = new int[totalStates];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        dp[0] = 0;

        for (int mask = 0; mask < totalStates; ++mask) {
            int i = Integer.bitCount(mask);
            if (i >= n) continue;
            for (int j = 0; j < n; ++j) {
                if ((mask & (1 << j)) == 0) {
                    int nextMask = mask | (1 << j);
                    dp[nextMask] = Math.min(dp[nextMask], dp[mask] + (nums1[i] ^ nums2[j]));
                }
            }
        }
        return dp[totalStates - 1];
    }
}

/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number}
 */
var minimumXORSum = function(nums1, nums2) {
    const n = nums1.length;
    const totalStates = 1 << n;
    const dp = Array(totalStates).fill(Infinity);
    dp[0] = 0;

    for (let mask = 0; mask < totalStates; ++mask) {
        let i = 0;
        let temp = mask;
        while (temp > 0) {
            i += temp & 1;
            temp >>= 1;
        }
        if (i >= n) continue;

        for (let j = 0; j < n; ++j) {
            if (!(mask & (1 << j))) {
                const nextMask = mask | (1 << j);
                const cost = dp[mask] + (nums1[i] ^ nums2[j]);
                if (cost < dp[nextMask]) dp[nextMask] = cost;
            }
        }
    }
    return dp[totalStates - 1];
};
